// Renvoie l'index du score d'attention le plus élevé.
// TODO : renvoyer toujours le dernier index est faux — il faut chercher le
//        maximum (égalités tranchées par le plus petit index).
export function mostAttended(scores) {
  return scores.length - 1;
}

